const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const text = (value, max = 2000) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const oneOf = (value, allowed, fallback) => allowed.includes(value) ? value : fallback;
const object = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const safeColors = object(body.palette);
const businessDna = object(body.businessDna);
const logo = object(body.logo);
const background = object(body.background);
const copy = object(body.copy);

const format = oneOf(text(body.format, 30), ['portrait', 'square', 'landscape', 'story', 'youtube'], 'portrait');
const topic = text(body.topic || body.rawBrief || body.userIdea || body.brief, 900) || 'Poster campaign';
const objective = text(body.objective, 120) || 'Generic poster';
const brandName = text(body.brandName || businessDna.brandName || logo.brandName, 120) || 'time2grow brand';

const payloadForAgents = {
  workflow: 'time2grow-poster-workflow-2',
  topic,
  rawBrief: text(body.rawBrief || body.userIdea || body.brief, 1800),
  promptContract: text(body.promptContract || body.brief, 2500),
  objective,
  preferredStyle: text(body.preferredStyle || body.style, 500),
  format,
  brandName,
  orgId: text(body.orgId, 90),
  userId: text(body.userId, 90),
  palette: safeColors,
  businessDna,
  logo: {
    url: text(logo.url || body.logoUrl, 2000),
    brandName,
    source: text(logo.source, 80) || 'business_dna',
  },
  background: {
    imageUrl: text(background.imageUrl, 2000),
    hasUploadedImageData: Boolean(text(background.imageDataUrl, 80)),
    opacity: typeof background.opacity === 'number' ? background.opacity : 1,
  },
  currentCopy: {
    headline: text(copy.headline, 160),
    subheadline: text(copy.subheadline, 260),
    callToAction: text(copy.callToAction, 80),
  },
  learningContext: text(body.learningContext, 2000),
};

const agentInput = [
  'Return strict json only.',
  'Analyze this time2grow Poster Studio request using the embedded poster-making skill rules.',
  JSON.stringify(payloadForAgents, null, 2),
].join('\n\n');

return [{
  json: {
    mode: text(body.mode || body.action, 80) || 'hybrid_poster',
    workflow: 'time2grow-poster-workflow-2',
    receivedAt: new Date().toISOString(),
    payloadForAgents,
    agentInput,
  },
}];

return [{
  json: {
    ok: true,
    workflow: 'time2grow-poster-workflow-2',
    message: 'time2grow poster workflow 2 is ready.',
    models: {
      planner: 'deepseek-v4-pro',
      promptAgent: 'OpenAI Chat Model',
      imageAgent: 'OpenAI image generation',
    },
  },
}];

function parseMaybeJson(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return {};
  const raw = value.trim().replace(/^\`\`\`json/i, '').replace(/^\`\`\`/, '').replace(/\`\`\`$/, '').trim();
  try { return JSON.parse(raw); } catch { return {}; }
}

const original = $('Normalize Poster Request').item.json.payloadForAgents;
const plan = parseMaybeJson($json.output || $json.text || $json);
if (!plan || !plan.headline || !plan.imagePrompt) {
  throw new Error('DeepSeek poster agent did not return a usable poster plan.');
}

const sizeByFormat = {
  square: '1024x1024',
  portrait: '1024x1536',
  story: '1024x1536',
  landscape: '1536x1024',
  youtube: '1536x1024',
};

const openAiAgentInput = {
  task: 'Convert the DeepSeek poster plan into a final OpenAI image-generation prompt.',
  important: [
    'Keep the actual topic visible in the poster copy plan.',
    'The OpenAI image should focus on artwork/background and design atmosphere.',
    'Do not ask the image model to render final readable text; text/logo are overlaid in the app canvas.',
    'If a logo URL or uploaded background exists, mention it only as visual reference context. Do not invent the logo.',
  ],
  requestedSize: sizeByFormat[original.format] || '1024x1536',
  originalRequest: original,
  deepSeekPosterPlan: plan,
};

return [{
  json: {
    workflow: 'time2grow-poster-workflow-2',
    original,
    plan,
    requestedSize: sizeByFormat[original.format] || '1024x1536',
    openAiAgentInput: JSON.stringify(openAiAgentInput, null, 2),
  },
}];

