function parseMaybeJson(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return {};
  const raw = value.trim().replace(/^\`\`\`json/i, '').replace(/^\`\`\`/, '').replace(/\`\`\`$/, '').trim();
  try { return JSON.parse(raw); } catch { return {}; }
}

const source = $('Build OpenAI Agent Input').item.json;
const openAiPlan = parseMaybeJson($json.output || $json.text || $json);
const imagePrompt = String(openAiPlan.openai_prompt || source.plan.imagePrompt || '').trim();
if (!imagePrompt) throw new Error('OpenAI prompt agent did not return a usable image prompt.');

const guardrails = [
  'No text, no words, no letters, no numbers.',
  'No fake logo, no watermark, no QR code.',
  'No invented contact details, discounts, guarantees, awards, or testimonials.',
  'Leave clean safe space for real browser-rendered logo, headline, subheadline, and CTA overlays.',
].join(' ');

const palette = source.plan.colors || source.original.palette || {};
const openAiPrompt = [
  imagePrompt,
  'Brand palette: ' + JSON.stringify(palette) + '.',
  'Format: ' + source.original.format + '. Export target is handled by time2grow canvas.',
  'Topic lock: poster must visually support this exact topic: ' + source.original.topic + '.',
  source.original.logo && source.original.logo.url ? 'A real brand logo is available and will be overlaid by the app. Do not invent a logo in the artwork.' : 'No logo artwork should be generated.',
  source.original.background && source.original.background.imageUrl ? 'User supplied a background reference URL; keep style compatible with that reference if visible to the model.' : '',
  guardrails,
].filter(Boolean).join('\n');

return [{
  json: {
    workflow: 'time2grow-poster-workflow-2',
    original: source.original,
    plan: source.plan,
    openAiPlan,
    openAiPrompt,
    imageSize: openAiPlan.image_size || source.requestedSize,
    imageQuality: openAiPlan.quality || 'high',
  },
}];

const source = $('Build OpenAI Image Prompt').item.json;
const item = $input.first();
const binaryName = item.binary && item.binary.poster ? 'poster' : (item.binary && item.binary.data ? 'data' : '');
let imageDataUrl = '';

if (binaryName) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryName);
  const binary = item.binary[binaryName] || {};
  const mimeType = binary.mimeType || 'image/png';
  imageDataUrl = 'data:' + mimeType + ';base64,' + buffer.toString('base64');
}

const plan = source.plan || {};
const layers = Array.isArray(plan.typography_layers) ? plan.typography_layers : [];
const first = (index) => layers[index] && typeof layers[index].text === 'string' ? layers[index].text : '';

const headline = String(plan.headline || first(0) || source.original.currentCopy.headline || source.original.topic || '').trim();
const subheadline = String(plan.subheadline || first(1) || source.original.currentCopy.subheadline || '').trim();
const callToAction = String(plan.callToAction || first(2) || source.original.currentCopy.callToAction || 'Learn more').trim();

return [{
  json: {
    ok: true,
    workflow: 'time2grow-poster-workflow-2',
    mode: 'hybrid_poster',
    source: 'n8n-ai-agent',
    imageDataUrl,
    copy: { headline, subheadline, callToAction },
    canvas_layout: {
      suggested_background_hex: plan.canvasLayout && plan.canvasLayout.suggested_background_hex ? plan.canvasLayout.suggested_background_hex : (plan.colors && plan.colors.bg ? plan.colors.bg : undefined),
      safe_zones: {
        logo_placement: plan.canvasLayout && plan.canvasLayout.logo_placement ? plan.canvasLayout.logo_placement : 'top_left',
        text_placement: plan.canvasLayout && plan.canvasLayout.text_placement ? plan.canvasLayout.text_placement : 'bottom',
      },
    },
    typography_layers: layers,
    plan,
    openAiPlan: source.openAiPlan,
    openAiPrompt: source.openAiPrompt,
    imageSize: source.imageSize,
    logoUrl: source.original.logo ? source.original.logo.url : '',
    backgroundImageUrl: source.original.background ? source.original.background.imageUrl : '',
    generatedAt: new Date().toISOString(),
  },
}];
